from lib import *
S = SS('f53')
R = J('f53'); dp = R['depth']
steps = [
    step("基本继承:base.html 定义 title、content、footer 三个 block;child.html 用 {% extends \"base.html\" %} 只覆盖 title(「子页面 - {{ super() }}」)与 content(<h1>{{ heading }}</h1>)。渲染结果:<title>子页面 - 默认标题</title>、<h1>你好</h1>,没覆盖的 footer 用父模板的 <footer>© base</footer>。super() 取父模板里这个 block 的内容。", t=tl(S(1)), done=lidx(S(1), '[base.html]', '[child.html]'), mark=lidx(S(1), '渲染 child.html'), kv=KV([['覆盖的 block', 'title、content'], ['没覆盖的', 'footer 用父模板的'], ['super()', '父模板里该 block 的内容']], ['super()'])),
    step("多级继承 grand → child → base:grand 覆盖 content({{ super() }} 取到 child 的 <h1>你好</h1>,再追加 <p>孙页面追加</p>)与 footer(孙页脚|{{ super() }} → 孙页脚|© base);title 沿用 child 的「子页面 - 默认标题」。super() 逐级向上取。", t=tl(S(2)), done=lidx(S(2), '渲染 grand.html'), kv=KV([['content', 'super() 取 child 的再追加'], ['footer', '孙页脚|© base'], ['title', '沿用 child']], ['content'])),
    step("嵌套 block:覆盖内层 block inner 时外层 outer 保留:nested_child → [外 内被覆盖]。子模板里写在 block 之外的内容会被忽略:noblock_child.html 在 {% extends %} 之后写了一句文字,但渲染结果与 base.html 的默认内容相同(<title>默认标题</title>…基础内容…),那句文字没有出现。", t=tl(S(3)), done=lidx(S(3), 'nested_child'), mark=lidx(S(3), '只有文字的子模板'), kv=KV([['覆盖内层 block', '外层保留'], ['block 之外的文字', '被忽略']], ['block 之外的文字'])),
    step("循环里的 block 与作用域:父模板在 {% for x in items %} 里放了 block item;没有 scoped 时子模板的 block 里读不到循环变量 x,结果 '子 未定义|子 未定义|';给父模板的 block 加 scoped(block item scoped)后,子模板的 block 能读到 x,结果 '子 1|子 2|'。", t=tl(S(4)), done=lidx(S(4), '没有 scoped'), mark=lidx(S(4), 'scoped     '), kv=KV([['没有 scoped', '循环变量不可见 → 未定义'], ['scoped', '循环变量可见 → 子 1|子 2|']], ['scoped'])),
    step("self.block 名():在同一个模板里复用某个 block 的渲染结果:<title>{% block title %}页面{% endblock %}</title><h1>{{ self.title() }}</h1> 渲染成 <title>页面</title><h1>页面</h1>,<title> 与 <h1> 保持一致,不必写两遍。", t=tl(S(5)), done=lidx(S(5), '<title>页面</title>'), kv=KV([['self.title()', '复用 title block 的输出']], ['self.title()'])),
    step("动态继承:{% extends layout %} 里的 layout 可以是变量:layout='alt_layout.html' 得到 <main>动态布局内容</main>;layout='base.html' 得到完整的 base 页面,content 里是「动态布局内容」;没有传 layout 时抛 UndefinedError: 'layout' is undefined。", t=tl(S(6)), done=lidx(S(6), "layout='alt_layout.html'", "layout='base.html'"), mark=lidx(S(6), 'layout 缺失'), kv=KV([['layout 是变量', '可以按条件选布局'], ['没传', 'UndefinedError']], ['layout 是变量'])),
    step("{% extends %} 前面写了文字不会报错,文字照样输出(前面有文字\\n<html>…);子模板顶层的 {% set shared = \"子里 set\" %} 对父模板可见:[子里 set]b:子里 set。{% include %} 默认带上当前上下文(<1>),without context 看不到 v(<无v>),ignore missing 跳过不存在的模板(空)。", t=tl(S(7)), done=lidx(S(7), 'extends 前面有文字', '子模板里 {% set %}'), mark=lidx(S(7), 'include 默认带 context'), kv=KV([['extends 前的文字', '照样输出'], ['顶层 set', '父模板可见'], ['include', '默认带 context;without context 不带']], ['include'])),
    step(f"继承的深度成本(每层只覆盖一个 block 并用 super()):0 层 {dp['0']:.1f} µs;3 层 {dp['3']:.1f} µs;10 层 {dp['10']:.1f} µs。每多一层约 {(dp['10'] - dp['0']) / 10:.1f} µs,继承本身很便宜,不必为了性能压平层级。", t=tl(S(8)), b=bars([['0 层', dp['0'], f"{dp['0']:.1f} µs"], ['3 层', dp['3'], f"{dp['3']:.1f} µs"], ['10 层', dp['10'], f"{dp['10']:.1f} µs"]], dp['10'], done=[0, 1, 2]), kv=KV([['0 层', f"{dp['0']:.1f} µs"], ['3 层', f"{dp['3']:.1f} µs"], ['10 层', f"{dp['10']:.1f} µs"]], ['10 层'])),
]
A = mkartf('f53', 53, 'Flask,Jinja2,模板继承,block,真实验证,动画演示',
    f'实测 Jinja2 模板继承:block 覆盖与 super();多级继承;嵌套 block;循环里的 block 要加 scoped 才能读到循环变量;self.block;动态 extends;extends 前的文字照样输出;include 的 context 选项;继承每多一层约 {(dp["10"] - dp["0"]) / 10:.1f} µs。',
    '{% extends %} 与 {% block %} 到底怎么工作?super() 取的是什么?block 里为什么看不到循环变量?继承层数多了会不会慢?这篇用最小的模板把每个规则渲染一遍。',
    [('scoped', '让 block 能读到循环变量的修饰'), (f'{dp["10"]:.1f} µs', '10 层继承的一次渲染耗时'), ('忽略', '子模板里写在 block 之外的内容的下场')],
    [('基本继承与 super()', '<p>上一篇:<a href="flask-template-search-path.html">Flask 模板搜索路径</a>;下一篇:<a href="flask-context-processor.html">Context Processor</a>。</p>'), ('多级继承', None), ('嵌套 block', None), ('循环里的 block', None), ('self.block', None), ('动态继承', None), ('extends 的位置与 include', None), ('继承的成本', None)],
    steps, [ENV_F, '没有验证:{% import %} 与继承的交互、{% block %} 的 required 修饰(Jinja 3.1 新增)、异步模板、宏在子模板 block 里的作用域'], '模板继承')
